from collections import deque
seen=set(); q=deque()
for r in range(R):
 for c in range(C):
  if (r in (0,R-1) or c in (0,C-1)) and grid[r][c]!=7:
   seen.add((r,c));q.append((r,c))
while q:
 r,c=q.popleft()
 for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
  nr,nc=r+dr,c+dc
  if 0<=nr<R and 0<=nc<C and grid[nr][nc]!=7 and (nr,nc) not in seen:
   seen.add((nr,nc));q.append((nr,nc))
holes=[(r,c) for r in range(R) for c in range(C) if grid[r][c]!=7 and (r,c) not in seen]
len(holes),holes

holeset=set(holes); comps=[]
while holeset:
 st=holeset.pop(); comp={st}; qq=[st]
 while qq:
  r,c=qq.pop()
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   p=(r+dr,c+dc)
   if p in holeset: holeset.remove(p);comp.add(p);qq.append(p)
 comps.append(comp)
[(len(x), (min(r for r,c in x),max(r for r,c in x),min(c for r,c in x),max(c for r,c in x))) for x in comps]

def floodholes(diag=False):
 ds=[(1,0),(-1,0),(0,1),(0,-1)]
 if diag: ds += [(1,1),(1,-1),(-1,1),(-1,-1)]
 se=set();qq=deque()
 for r in range(R):
  for c in range(C):
   if (r in (0,R-1) or c in (0,C-1)) and grid[r][c]!=7: se.add((r,c));qq.append((r,c))
 while qq:
  r,c=qq.popleft()
  for dr,dc in ds:
   p=(r+dr,c+dc)
   if 0<=p[0]<R and 0<=p[1]<C and grid[p[0]][p[1]]!=7 and p not in se: se.add(p);qq.append(p)
 return {(r,c) for r in range(R) for c in range(C) if grid[r][c]!=7 and (r,c) not in se}
h4=floodholes();h8=floodholes(True)
len(h4),len(h8),sorted(h4-h8),sorted(h8-h4)

# Label 4-connected components of marker and record which touch each hole's neighboring boundary.
mark={(r,c) for r in range(R) for c in range(C) if grid[r][c]==7}
compid={}; comps=[]
for p in mark:
 if p in compid: continue
 k=len(comps); cc={p}; compid[p]=k; stack=[p]
 while stack:
  r,c=stack.pop()
  for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
   q=(r+dr,c+dc)
   if q in mark and q not in compid: compid[q]=k;cc.add(q);stack.append(q)
 comps.append(cc)
[(len(c), (min(r for r,c in c), max(r for r,c in c), min(c for r,c in c), max(c for r,c in c))) for c in comps]
